/**
 * Regenerates the component graph in `docs/architecture.md` (technical-plan 6.1: "The package
 * graph is documented in docs/architecture.md and regenerated by CI").
 *
 *   node tools/architecture/generate.mjs            write the file
 *   node tools/architecture/generate.mjs --check    fail if the file is stale
 *
 * dependency-cruiser gives us module-level edges; this collapses them to the components a
 * reader cares about — one node per workspace package and one per server layer — so the
 * picture stays legible as the tree grows.
 */

import { execFile } from "node:child_process";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { promisify } from "node:util";

const run = promisify(execFile);

const REPO = fileURLToPath(new URL("../../", import.meta.url));
const CRUISER = fileURLToPath(new URL("../../node_modules/.bin/depcruise", import.meta.url));
const TARGET = fileURLToPath(new URL("../../docs/architecture.md", import.meta.url));
const TEMPLATE = fileURLToPath(new URL("./architecture.template.md", import.meta.url));

const SOURCE_ROOTS = ["packages", "apps", "adapters", "examples", "server", "cli", "relay"];
const BEGIN = "<!-- generated:graph -- do not edit by hand; run pnpm gen:architecture -->";
const END = "<!-- /generated:graph -->";
const NOISE = "(^|/)node_modules/|(^|/)(dist|coverage|target|[.]turbo|[.]git)(/|$)|^(docs|tools)/";

/** Which component a module belongs to. Undefined for files outside the graph. */
function componentOf(source) {
  const layered = /^(server|cli|relay)\/src\/([^/]+)\//.exec(source);
  if (layered) return `${layered[1]}/${layered[2]}`;

  const workspace = /^(packages|apps|adapters|examples)\/([^/]+)\//.exec(source);
  if (workspace) return `${workspace[1]}/${workspace[2]}`;

  const top = /^(server|cli|relay)\//.exec(source);
  return top ? top[1] : undefined;
}

/** Packages that exist for the clients: the design system, and the state and protocol client. */
const CLIENT_PACKAGES = ["packages/ui", "packages/core"];

/** The band a component is drawn in, in the order the bands appear. */
const BANDS = [
  ["Protocol", (c) => c === "packages/protocol"],
  ["Domain", (c) => c.endsWith("/domain")],
  ["Application", (c) => c.endsWith("/application")],
  ["Infrastructure", (c) => c.endsWith("/infrastructure")],
  ["Interfaces", (c) => c.endsWith("/interfaces") || c === "cli"],
  ["Clients and docs", (c) => c.startsWith("apps/") || CLIENT_PACKAGES.includes(c)],
  ["Adapters and examples", (c) => c.startsWith("adapters/") || c.startsWith("examples/")],
  ["Cross-cutting", (c) => c === "packages/platform"],
  ["Shared packages", () => true],
];

function bandOf(component) {
  const band = BANDS.find(([, matches]) => matches(component));
  return band ? band[0] : "Shared packages";
}

function nodeId(component) {
  let hash = 7;
  for (const character of component) hash = (hash * 33 + character.charCodeAt(0)) % 1_000_000_007;
  return `n${hash}`;
}

async function collectEdges() {
  const roots = SOURCE_ROOTS.filter((root) => existsSync(`${REPO}${root}`));
  if (roots.length === 0) return { components: [], edges: [] };

  const { stdout } = await run(
    CRUISER,
    [
      "--config",
      `${REPO}.dependency-cruiser.cjs`,
      "--exclude",
      NOISE,
      "--output-type",
      "json",
      ...roots,
    ],
    { cwd: REPO, maxBuffer: 64 * 1024 * 1024 },
  ).catch((error) => ({ stdout: error.stdout || "" }));

  const { modules } = JSON.parse(stdout);
  const components = new Set();
  const edges = new Set();

  for (const module of modules) {
    const from = componentOf(module.source);
    if (from === undefined) continue;
    components.add(from);
    for (const dependency of module.dependencies) {
      const to = componentOf(dependency.resolved);
      if (to === undefined || to === from) continue;
      components.add(to);
      edges.add(`${from}|${to}`);
    }
  }
  return { components: [...components].sort(), edges: [...edges].sort() };
}

function renderGraph({ components, edges }) {
  if (components.length === 0) return "_No source packages yet._";

  const lines = ["```mermaid", "flowchart TD"];
  for (const [band] of BANDS) {
    const members = components.filter((component) => bandOf(component) === band);
    if (members.length === 0) continue;
    lines.push(`  subgraph ${band.replace(/[^A-Za-z0-9]/g, "_")}["${band}"]`);
    for (const member of members) lines.push(`    ${nodeId(member)}["${member}"]`);
    lines.push("  end");
  }
  for (const edge of edges) {
    const [from, to] = edge.split("|");
    lines.push(`  ${nodeId(from)} --> ${nodeId(to)}`);
  }
  lines.push("```");
  return lines.join("\n");
}

const graph = renderGraph(await collectEdges());
const next = readFileSync(TEMPLATE, "utf8").replace(
  `${BEGIN}\n${END}`,
  `${BEGIN}\n\n${graph}\n\n${END}`,
);

if (process.argv.includes("--check")) {
  const current = existsSync(TARGET) ? readFileSync(TARGET, "utf8") : "";
  if (current !== next) {
    console.error("docs/architecture.md is stale. Run: pnpm gen:architecture");
    process.exit(1);
  }
  console.log("docs/architecture.md is up to date.");
} else {
  writeFileSync(TARGET, next);
  console.log("Wrote docs/architecture.md");
}
